DB["topics/traversal"] = {
        title: 'Array Traversal',
        crumbs: ['Home', 'Data Structures', 'Array', 'DSA & DAA Topics', 'Traversal'],
        tags: ['array', 'traversal', 'iteration', 'forward', 'reverse', 'stride'],
        content: [
            '# Array Traversal',
            '',
            '> **Definition.** Traversal means visiting every element of an array **exactly once**, in a defined order. It is the base of every array algorithm: summing, counting, searching, prefix/suffix computations, and both pointer sweeps are just traversals with a little extra bookkeeping.',
            '',
            '## History & Origin',
            '',
            'The array is one of computing\'s oldest data structures — a block of contiguous memory cells addressed by consecutive integers — and goes back to the earliest stored-program machines, whose sequential architecture naturally reads memory in order. Counting loops arrived with the first high-level languages (FORTRAN, 1957) and are how programs say "do this to every element". [Wikipedia: Array data structure](https://en.wikipedia.org/wiki/Array_data_structure), [Wikipedia: Loop (computer science)](https://en.wikipedia.org/wiki/Loop_%28computer_science%29)',
            '',
            'Forward traversal is also the most **cache-friendly** order in modern CPUs: adjacent array cells sit in adjacent cache lines, so scanning 0→n-1 is close to the fastest memory behaviour a program can have. This is why "walk the array once" is the gold standard — it is both asymptotically and practically cheap.',
            '',
            '## Intuition',
            '',
            'Imagine a row of numbered lockers. **Forward traversal** visits lockers 0, 1, 2, … in order; **reverse traversal** visits them from the far end back. Use forward when the answer at position `i` depends on what lies to the *left* (prefix sums), and reverse when it depends on what lies to the *right* (suffix maxima, next-greater element). Two-pointer algorithms simply run two traversals at once.',
            '',
            '## Traversal Patterns',
            '',
            '| Pattern | Loop | Typical use |',
            '|---|---|---|',
            '| Forward | `for i in 0..n-1` | Sum, count, find, prefix |',
            '| Reverse | `for i in n-1..0` | Suffix queries, next-greater |',
            '| Stride | `i += k` | Every k-th element, sampling |',
            '| Expand out | `l = i, r = i`, grow | Palindromes |',
            '| Two pointers | `l` and `r` together | Merge, dedupe, pair search |',
            '',
            '## Step-by-Step Trace',
            '',
            'For `a = [2, 5, 1, 8, 3]`, a **forward traversal** visiting each element:',
            '',
            '| Step | i | a[i] | Action |',
            '|---|---|---|---|',
            '| 1 | 0 | 2 | Visit element |',
            '| 2 | 1 | 5 | Visit element |',
            '| 3 | 2 | 1 | Visit element |',
            '| 4 | 3 | 8 | Visit element |',
            '| 5 | 4 | 3 | Visit element |',
            '',
            'Every index visited exactly once — **O(n)**. Add bookkeeping (sum, count, compare) and you get every linear array algorithm.',
            '',
            '## Complexity',
            '',
            '| Aspect | Value | Why |',
            '|---|---|---|',
            '| Time | **O(n)** | Each element visited exactly once per pass |',
            '| Space | **O(1)** | Only loop variables needed |',
            '| Cache | Excellent | Forward scans hit sequential cache lines |',
            '',
            '> [!success] The key insight',
            '> A single clean pass is the cheapest thing a program can do — always start from "can I do it in one traversal?" before reaching for nested loops.',
            '',
            '## Edge Cases',
            '',
            '1. **Empty array** → the loops never run; seed accumulators for the empty case or guard first.',
            '2. **Single element** → `a[n-1]` is `a[0]`; trivially correct.',
            '3. **All equal** → any comparison-based bookkeeping stays constant; still correct.',
            '4. **Very large sums** → use 64-bit integers to avoid overflow while summing.',
            '',
            '## Common Mistakes',
            '',
            '- **Off-by-one bounds**: `i < n` not `i <= n` (would read past the end).',
            '- **Reverse loop with an unsigned index**: `for (size_t i = n-1; i >= 0; i--)` never terminates — `i` wraps around. Use signed indices or a while loop.',
            '- **Modifying the array while reading it forward** — you may revisit changed values.',
            '- **Assuming the array is sorted** — traversal itself never assumes order; extra patterns do.',
            '',
            '## Applications',
            '',
            'Every linear-time array algorithm is traversal plus bookkeeping:',
            '',
            '- **Forward Sum** builds on forward traversal — see [Forward Sum](topics/forward-sum).',
            '- **Suffix Max** builds on reverse traversal — see [Suffix Max](topics/suffix-max).',
            '- **Prefix Sum** builds on forward traversal — see [Prefix Sum](topics/prefix-sum).',
            '- **Sliding window / two pointers** are two coordinated traversals.',
            '- **In-place dedupe and partition** use a fast traversal that reads and a slow one that writes.',
            '- **GPU/vectorized code** parallelizes pure traversals (map/scan) across cores. [Wikipedia: MapReduce](https://en.wikipedia.org/wiki/MapReduce)',
            '',
            '> [!tip] Try it yourself',
            '> Code a forward sum and a reverse suffix max from scratch in your preferred language, then compare with the programs on those dedicated pages.'
        ].join('\n')
  };

