            '# Suffix Max',
            '',
            '> **Definition.** Suffix max computes, for each position `i`, the maximum value in the subarray `a[i..n-1]` by scanning right to left (index n-1 → 0). It is the canonical application of reverse traversal and the building block for "next greater element", "stock span", and many stack-based problems.',
            '',
            '## History & Origin',
            '',
            'Suffix queries are fundamental in algorithm design. The suffix max (also called "suffix maximum" or "right-to-left max") appears in problems ranging from stock pricing to histogram analysis. The technique is closely related to the "next greater element" pattern and monotonic stacks. [Wikipedia: Suffix array](https://en.wikipedia.org/wiki/Suffix_array)',
            '',
            '## Intuition',
            '',
            'Start from the last element and walk backwards. Keep a running `best` — the largest value seen so far from the right. At each position `i`, update `best = max(best, a[i])` and record it. After the scan, `suf[i]` holds the maximum of `a[i..n-1]`.',
            '',
            '## Step-by-Step Trace',
            '',
            'For `a = [2, 5, 1, 8, 3]`:',
            '',
            '| Step | i | a[i] | best before | best after | suf[i] |',
            '|---|---|---|---|---|---|',
            '| 1 | 4 | 3 | -∞ | 3 | 3 |',
            '| 2 | 3 | 8 | 3 | 8 | 8 |',
            '| 3 | 2 | 1 | 8 | 8 | 8 |',
            '| 4 | 1 | 5 | 8 | 8 | 8 |',
            '| 5 | 0 | 2 | 8 | 8 | 8 |',
            '',
            'Suffix max array = `[8, 8, 8, 8, 3]`. One reverse pass, exactly `n` comparisons.',
            '',
            '## The Program',
