            '    for (int i = 0; i <= n; i++) printf("%d ", pref[i]);',
            '    printf("\\n");',
            '    printf("sum(1..3) = %d\\n", pref[4] - pref[1]);',
            '    printf("sum(0..4) = %d\\n", pref[5] - pref[0]);',
            '    return 0;',
            '}',
            '---',
            '##1## Includes the standard input/output header so `printf` is available. [stdio]({c:stdio})',
