            '##5## The prefix array is one cell bigger than `a`. [Arrays]({c:array})',
            '##6## The sentinel `pref[0] = 0` removes every `l = 0` edge case. [Arrays]({c:array})',
            '##7## Build pass: each cell is the previous total plus the next element. [For loops]({c:for})',
            '##8## Prints the `pref = ` label. [printf]({c:printf})',
