            '',
            '## Common Mistakes',
            '',
            '- **Off-by-one in the query formula**: the 0-based inclusive form is `pref[r+1] - pref[l]`; mixing in `pref[r]` gives the wrong window.',
            '- **Forgetting `pref[0] = 0`** — without the sentinel, `l = 0` queries underflow.',
            '- **Mutating `a` after building `pref`** — the prefix cache goes stale.',
            '- **Rebuilding `pref` inside a loop** — that defeats the O(1) query; build it once.',
            '',
            '## Applications',
            '',
            '- **Subarray sum equals k** — pair `pref` with a hashmap of first occurrences.',
            '- **Range sums / range averages** (LeetCode 303, 304).',
            '- **2D image blur & matrix queries** — box sums in O(1) per window.',
            '- **Count of subarrays divisible by k** — bucket the `pref` remainders.',
            '- **Balanced parentheses / stock differences** — the prefix of a +1/-1 array locates imbalances.',
            '',
            '> [!tip] Try it yourself',
