            '##4## `diff` is size `n+1` — the `-v` at `diff[n]` needs the extra cell. [Arrays]({c:array})',
            '##5## `+3` on `[1..4]`: `+v` at `l`, `-v` at `r+1`. [Arrays]({c:array})',
            '##6## `+2` on `[2..3]`. [Arrays]({c:array})',
            '##7## `+5` on `[0..1]`. [Arrays]({c:array})',
            '##8## Prints the `diff = ` label. [printf]({c:printf})',
