            '# Two Pointers',
            '',
            '> **Definition.** The two-pointer pattern runs two index variables through one array — from opposite ends, or at different speeds — so that problems which look O(n²) collapse to **O(n) time and O(1) extra space**. Any "pair elements of a sorted array" problem is a candidate.',
            '',
            '## History & Origin',
            '',
