            '',
            'The slow/fast pointer pair dates to **Floyd\'s cycle-finding algorithm** (1967), which uses a tortoise and a hare to detect cycles in linked structures. As an interview technique the pattern was popularised by problems like "Two Sum II" (sorted input) and "Container With Most Water", where the two ends of a sorted array are walked toward each other. [GeeksforGeeks: Two Pointers Technique](https://www.geeksforgeeks.org/two-pointers-technique/)',
