            '',
            '## Why It Works (proof sketch)',
            '',
            'The array is sorted. If `a[l] + a[r] < target`, then for this `l`, every other candidate `a[l] + a[j]` with `j <= r` is even smaller — so `l` can be **discarded forever** and `l++` is safe. Symmetrically, if `a[l] + a[r] > target`, every `a[i] + a[r]` with `i >= l` is even larger, so `r` can be discarded and `r--` is safe. The hands never turn back, so at most `n` probes happen before they cross.',
