            '- **Forgetting the "not found" branch** — the loop can end without a hit.',
            '',
            '## Applications',
            '',
            '- **Two Sum II** (sorted) and **3-Sum** — pair/triple searches in O(n) / O(n²).',
            '- **Container With Most Water** — maximize area with a shrinking width.',
            '- **Remove duplicates in place** — slow writer, fast reader.',
            '- **Move zeros / partition** — one pointer writes, the other reads.',
