            '##4## A `vector` is a growable, bounds-aware array. [vector]({cpp:vector})',
            '##5## `best` holds the largest sum seen anywhere, seeded with the first element. [Variables](https://www.learn-c.org/en/Variables)',
            '##6## `cur` is the best sum of a subarray ending at the current index. [Variables](https://www.learn-c.org/en/Variables)',
            '##7## Loop from the second element onward; index 0 was already used. [for](https://en.cppreference.com/w/cpp/language/for)',
            '##8## A negative `cur` can only shrink the sum — restart at `a[i]`. [if](https://en.cppreference.com/w/cpp/language/if)',
            '##9## Otherwise extend the best subarray ending just before with `a[i]`. [Variables](https://www.learn-c.org/en/Variables)',
            '##10## `max` keeps the larger of the two candidates. [max]({cpp:max})',
            '##11## Writes the maximum subarray sum and a newline. [cout]({cpp:cout})',
