            '',
            '~~~explain',
            'lang: java',
            'group: kadane',
            'import java.util.*;',
            'public class Main {',
            '    public static void main(String[] args) {',
            '        int[] a = {-2, 1, -3, 4, -1, 2, 1, -5, 4};',
            '        int best = a[0];',
            '        int cur = a[0];',
            '        for (int i = 1; i < a.length; i++) {',
            '            if (cur < 0) cur = a[i];',
