            '##4## A fixed-size array; `length` gives its size. [Arrays](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/arrays.html)',
            '##5## `best` holds the largest sum seen anywhere, seeded with the first element. [Variables](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/variables.html)',
            '##6## `cur` is the best sum of a subarray ending at the current index. [Variables](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/variables.html)',
            '##7## Loop from the second element onward. [for]({java:for})',
            '##8## A negative `cur` can only shrink the sum — restart at `a[i]`. [if]({java:if})',
            '##9## Otherwise extend the best subarray ending just before with `a[i]`. [Variables](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/variables.html)',
            '##10## `Math.max` picks the larger candidate. [Math]({java:Math})',
