            '    a = [-2, 1, -3, 4, -1, 2, 1, -5, 4]',
            '    best = a[0]',
            '    cur = a[0]',
            '    for x in a[1:]:',
            '        if cur < 0:',
            '            cur = x',
            '        else:',
            '            cur += x',
            '        if cur > best:',
            '            best = cur',
