            'main()',
            '---',
            '##1## Defines the function; indentation marks its body. [def]({python:def})',
            '##2## A list of integers. [list]({python:list})',
            '##3## `best` holds the largest sum seen anywhere, seeded with the first element. [Variables](https://www.w3schools.com/python/python_variables.asp)',
            '##4## `cur` is the best sum of a subarray ending at the current element. [Variables](https://www.w3schools.com/python/python_variables.asp)',
            '##5## `a[1:]` is every element except the first — loop over the rest. [list]({python:list})',
            '##6## If `cur` is negative, extending would only shrink the sum. [if]({python:if})',
            '##7## Start a fresh subarray at `x`. [Variables](https://www.w3schools.com/python/python_variables.asp)',
            '##8## Otherwise... [if]({python:if})',
            '##9## ...extend the best subarray ending before with `x`. [Variables](https://www.w3schools.com/python/python_variables.asp)',
            '##10## If this ending-sum beats the all-time best... [if]({python:if})',
            '##11## ...remember it. [Variables](https://www.w3schools.com/python/python_variables.asp)',
