            '~~~explain',
            'lang: dart',
            'group: kadane',
            'void main() {',
            '  var a = [-2, 1, -3, 4, -1, 2, 1, -5, 4];',
            '  var best = a[0];',
            '  var cur = a[0];',
            '  for (var i = 1; i < a.length; i++) {',
            '    if (cur < 0) {',
            '      cur = a[i];',
            '    } else {',
            '      cur += a[i];',
            '    }',
            '    if (cur > best) {',
            '      best = cur;',
            '    }',
            '  }',
            '  print(best);',
            '}',
