            '# Bubble Sort',
            '',
            '> **Definition.** Bubble sort repeatedly steps through the array, compares adjacent elements, and swaps them if they are in the wrong order. The pass through the array is repeated until the array is sorted. Larger elements "bubble" to the end with each pass.',
            '',
            '## History & Origin',
            '',
            'Bubble sort is one of the simplest sorting algorithms. It was first described in 1956 by **John Mauchly** in a UNIVAC I report. The name comes from the way larger elements "bubble" to the top (end) of the array. [Wikipedia: Bubble sort](https://en.wikipedia.org/wiki/Bubble_sort)',
            '',
            '## Intuition',
            '',
            'Imagine bubbles rising in water — the largest unsorted element rises to its correct position at the end of the array in each pass. Compare each pair of adjacent elements and swap if out of order. After one pass, the largest element is in its final position.',
            '',
            '## Step-by-Step Trace',
            '',
            'For `a = [5, 3, 8, 1, 2]`:',
            '',
            '| Pass | Comparisons & Swaps | Array after pass |',
            '|---|---|---|',
            '| 1 | (5,3) swap, (5,8) ok, (8,1) swap, (8,2) swap | `[3, 5, 1, 2, 8]` |',
            '| 2 | (3,5) ok, (5,1) swap, (5,2) swap | `[3, 1, 2, 5, 8]` |',
            '| 3 | (3,1) swap, (3,2) swap | `[1, 2, 3, 5, 8]` |',
            '| 4 | no swaps — sorted | `[1, 2, 3, 5, 8]` |',
            '',
            '## The Program',
            '',
            '~~~explain',
            'lang: c',
            'group: bubblesort',
            '#include <stdio.h>',
            'int main() {',
            '    int a[] = {5, 3, 8, 1, 2};',
            '    int n = 5;',
            '    for (int i = 0; i < n - 1; i++) {',
            '        int swapped = 0;',
            '        for (int j = 0; j < n - i - 1; j++) {',
            '            if (a[j] > a[j + 1]) {',
            '                int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;',
            '                swapped = 1;',
            '            }',
            '        }',
            '        if (!swapped) break;',
            '    }',
            '    for (int i = 0; i < n; i++) printf("%d ", a[i]);',
            '    printf("\\n");',
            '    return 0;',
            '}',
