            '  if (a.length <= 1) return a;',
            '  int m = a.length ~/ 2;',
            '  var L = mergesort(a.sublist(0, m));',
            '  var R = mergesort(a.sublist(m));',
            '  return merge(L, R);',
            '}',
            '',
            'List<int> merge(List<int> L, List<int> R) {',
            '  var result = <int>[];',
            '  int i = 0, j = 0;',
            '  while (i < L.length && j < R.length) {',
            '    if (L[i] <= R[j])',
            '      result.add(L[i++]);',
            '    else',
            '      result.add(R[j++]);',
            '  }',
            '  result.addAll(L.sublist(i));',
            '  result.addAll(R.sublist(j));',
            '  return result;',
            '}',
            '',
