            '## Why It Works (invariant)',
            '',
            'After merging two sorted subarrays, the result is sorted. By induction, single elements are trivially sorted. Recursively merging sorted halves produces a fully sorted array.',
            '',
            '## Complexity',
            '',
            '| Aspect | Value |',
            '|---|---|',
            '| Time (best) | **O(n log n)** |',
            '| Time (avg) | **O(n log n)** |',
            '| Time (worst) | **O(n log n)** |',
            '| Space | **O(n)** — temporary arrays |',
            '| Stable | **Yes** |',
            '',
