            'void countingSortByDigit(List<int> a, int exp) {',
            '  int n = a.length;',
            '  var output = List.filled(n, 0);',
            '  var count = List.filled(10, 0);',
            '  for (var x in a) count[(x~/exp)%10]++;',
            '  for (var i = 1; i < 10; i++) count[i] += count[i-1];',
            '  for (var i = n-1; i >= 0; i--) {',
            '    int digit = (a[i]~/exp)%10;',
            '    count[digit]--;',
            '    output[count[digit]] = a[i];',
            '  }',
            '  a.setAll(0, output);',
            '}',
            '',
            'void radixsort(List<int> a) {',
            '  int m = a.reduce((a, b) => a > b ? a : b);',
            '  for (int exp = 1; m ~/ exp > 0; exp *= 10)',
            '    countingSortByDigit(a, exp);',
            '}',
            '',
