            '    var item = a[cs], pos = cs;',
            '    for (int i = cs + 1; i < n; i++)',
            '      if (a[i] < item) pos++;',
            '    if (pos == cs) continue;',
            '    while (item == a[pos]) pos++;',
            '    var temp = a[pos]; a[pos] = item; item = temp;',
            '    while (pos != cs) {',
            '      pos = cs;',
            '      for (int i = cs + 1; i < n; i++)',
            '        if (a[i] < item) pos++;',
            '      while (item == a[pos]) pos++;',
            '      temp = a[pos]; a[pos] = item; item = temp;',
            '    }',
            '  }',
            '}',
            '',
