            '',
            '## Why It Works (invariant)',
            '',
            'Each element is placed in its correct position by counting how many elements are smaller. The cycle continues until we return to the starting position, having placed all elements in the cycle correctly.',
            '',
            '## Complexity',
            '',
            '| Aspect | Value |',
            '|---|---|',
            '| Time | **O(n²)** |',
            '| Space | **O(1)** |',
            '| Stable | **No** |',
            '| Writes | **Optimal** — at most n-1 writes for unique elements |',
