            '            return',
            '        if a[m] < target:',
            '            print(f"probe mid={m} -> a[{m}] = {a[m]} < {target}, go right")',
            '            l = m + 1',
            '        else:',
            '            print(f"probe mid={m} -> a[{m}] = {a[m]} > {target}, go left")',
            '            r = m - 1',
            '    print("not found")',
            '',
            'main()',
            '---',
            '##1## Defines the function; indentation marks its body. [def]({python:def})',
            '##2## A sorted list of integers. [list]({python:list})',
            '##3## The value we are looking for. [Variables](https://www.w3schools.com/python/python_variables.asp)',
            '##4## The search space starts at the whole array. [list]({python:list})',
            '##5## `l <= r` keeps one probe alive at the end. [while](https://docs.python.org/3/reference/compound_stmts.html#while)',
            '##6## `//` is integer division, so `m` stays an index. [list]({python:list})',
            '##7## If the midpoint hits the target... [if]({python:if})',
            '##8## ...report the probe and the index. [print]({python:print})',
