            '##10## If the midpoint is too small... [if]({python:if})',
            '##11## ...report the probe. [print]({python:print})',
            '##12## ...and search only the right half. [Variables](https://www.w3schools.com/python/python_variables.asp)',
            '##14## Otherwise the midpoint is too big... [if]({python:if})',
            '##15## ...report the probe. [print]({python:print})',
