            '',
            '~~~explain',
            'lang: dart',
            'group: binary-search',
            'void main() {',
            '  var a = [1, 3, 5, 7, 9, 11, 13];',
            '  var target = 9;',
            '  var l = 0, r = a.length - 1;',
            '  while (l <= r) {',
            '    var m = (l + r) ~/ 2;',
            '    if (a[m] == target) {',
            '      print(\'probe mid=$m -> a[$m] = ${a[m]} == $target, found at $m\');',
            '      return;',
            '    }',
            '    if (a[m] < target) {',
            '      print(\'probe mid=$m -> a[$m] = ${a[m]} < $target, go right\');',
            '      l = m + 1;',
            '    } else {',
            '      print(\'probe mid=$m -> a[$m] = ${a[m]} > $target, go left\');',
            '      r = m - 1;',
            '    }',
            '  }',
            '  print(\'not found\');',
            '}',
            '---',
            '##1## Top-level entry point of a Dart program. [main]({dart:main})',
            '##2## A sorted list of integers. [List]({dart:List})',
            '##3## The value we are looking for. [var]({dart:var})',
            '##4## The search space starts at the whole array. [List]({dart:List})',
            '##5## `l <= r` keeps one probe alive at the end. [while]({dart:while})',
            '##6## `~/` is integer division, so `m` stays an index. [var]({dart:var})',
            '##7## If the midpoint hits the target... [if]({dart:if})',
            '##8## ...report the probe and the index. [print]({dart:print})',
            '##9## Leave the function immediately. [return](https://dart.dev/language/functions)',
            '##11## If the midpoint is too small... [if]({dart:if})',
            '##12## ...report the probe. [print]({dart:print})',
            '##13## ...and search only the right half. [var]({dart:var})',
            '##15## Otherwise the midpoint is too big... [if]({dart:if})',
            '##16## ...report the probe. [print]({dart:print})',
            '##17## ...and search only the left half. [var]({dart:var})',
            '##19## The range emptied: not present. [print]({dart:print})',
