            '',
            '~~~explain',
            'lang: c',
            'group: ternarysearch',
            '#include <stdio.h>',
            'int ternarySearch(int a[], int l, int r, int target) {',
            '    if (r >= l) {',
            '        int m1 = l + (r - l) / 3;',
            '        int m2 = r - (r - l) / 3;',
            '        if (a[m1] == target) return m1;',
            '        if (a[m2] == target) return m2;',
