            '##5## The frequency array, indexed by value (values < 100). [Arrays]({c:array})',
            '##6## Tracks the current champion and its count. [Variables](https://www.learn-c.org/en/Variables)',
            '##7## One pass over every element. [For loops]({c:for})',
            '##8## Increment the count for this value. [Arrays]({c:array})',
            '##9## If this value just took the lead... [If statements]({c:if})',
            '##10## ...record the new count. [Variables](https://www.learn-c.org/en/Variables)',
