            '# Complexity Analysis',
            '',
            '> **Definition.** Big-O describes how an algorithm\'s time or space usage **scales** with input size `n`, ignoring constants and lower-order terms. Complexity analysis is usually the first thing interviewers judge — before correctness and style.',
            '',
            '## History & Origin',
            '',
            'The O-notation was introduced by **Paul Bachmann** in *Die Analytische Zahlentheorie* (1894) and popularised by **Edmund Landau** (1909); the symbol `O` is therefore called "Bachmann–Landau notation". The formal theory of computational complexity followed in the 1960s with **Hartmanis and Stearns** (1965 Turing Award). [Wikipedia: Big O notation](https://en.wikipedia.org/wiki/Big_O_notation) · [Bachmann, Die Analytische Zahlentheorie (1894)](https://archive.org/details/dieanalytischez00bachgoog) · [Hartmanis & Stearns: On the computational complexity of algorithms (1965)](https://www.ams.org/journals/tran/1965-117-00/S0002-9947-1965-0170805-7/)',
            '',
            '## Intuition',
            '',
            'Big-O answers one question: *what happens when the input doubles?* An O(1) step stays constant, O(log n) grows by a constant amount, O(n) doubles, O(n²) quadruples, and exponential classes explode. Count the dominant loop structure and you have the class.',
            '',
            '## Step-by-Step Trace',
            '',
