            '---',
            '##1## Import [java.util](https://docs.oracle.com/javase/8/docs/api/java/util/package-summary.html) for Scanner and collections.',
            '##2## A plain [int array](https://docs.oracle.com/javase/tutorial/java/nutsandbasics/arrays.html) holds the input values.',
            '##3## The suffix array is one element longer to hold the zero [sentinel](https://en.wikipedia.org/wiki/Sentinel_value).',
            '##4## Build suffix sums with a reverse [for loop](https://docs.oracle.com/javase/tutorial/java/nutsandbasics/for.html).',
            '##5## Print each entry using [System.out.println](https://docs.oracle.com/javase/8/docs/api/java/io/PrintStream.html#println-java.lang.String-).',
            '##6## Range-sum query is O(1) via [subtraction](https://en.wikipedia.org/wiki/Subtraction) of two array values.',
            '~~~',
            '',
            '~~~explain',
            'lang: python',
            'group: suffixsum',
            'def main():',
            '    a = [2, 4, 6, 8, 10]',
            '    n = len(a)',
            '    sfx = [0] * (n + 1)',
            '    for i in range(n - 1, -1, -1):',
            '        sfx[i] = a[i] + sfx[i + 1]',
            '    for i in range(n):',
            '        print(f"sfx[{i}] = {sfx[i]}")',
            '    qi, qj = 1, 3',
            '    result = sfx[qi] - sfx[qj + 1]',
            '    print(f"Sum of a[{qi}..{qj}] = {result}")',
            'if __name__ == "__main__":',
            '    main()',
            '---',
            '##1## The input list `a` holds the [array](https://docs.python.org/3/library/stdtypes.html#sequence-types-list-tuple-range) values.',
            '##2## `sfx` is a list of n+1 zeros; the extra slot acts as a [sentinel](https://en.wikipedia.org/wiki/Sentinel_value).',
            '##3## `range(n-1, -1, -1)` iterates [backward](https://docs.python.org/3/library/stdtypes.html#range) through every index.',
            '##4## Each suffix sum accumulates the current element with all elements to its [right](https://en.wikipedia.org/wiki/Prefix_sum).',
            '##5## An f-string prints each value using Python\'s [formatted string literals](https://docs.python.org/3/reference/lexical_analysis.html#f-strings).',
            '##6## The range query is a single [subtraction](https://en.wikipedia.org/wiki/Subtraction) — O(1) time.',
            '##7## `if __name__` guards against [auto-execution](https://docs.python.org/3/library/__main__.html) when imported.',
            '~~~',
            '',
            '~~~explain',
            'lang: dart',
            'group: suffixsum',
            'void main() {',
            '  List<int> a = [2, 4, 6, 8, 10];',
            '  int n = a.length;',
            '  List<int> sfx = List<int>.filled(n + 1, 0);',
            '  for (int i = n - 1; i >= 0; i--) {',
            '    sfx[i] = a[i] + sfx[i + 1];',
            '  }',
            '  for (int i = 0; i < n; i++) {',
            '    print(\'sfx[$i] = ${sfx[i]}\');',
            '  }',
            '  int qi = 1, qj = 3;',
            '  int result = sfx[qi] - sfx[qj + 1];',
            '  print(\'Sum of a[$qi..$qj] = $result\');',
            '}',
            '---',
            '##1## A [List](https://api.dart.dev/stable/dart-core/List-class.html) holds the input array.',
            '##2## `List.filled` creates a fixed-size list initialized to [zero](https://api.dart.dev/stable/dart-core/int-class.html).',
            '##3## Loop runs backward from n-1 to 0, building the [suffix sum](https://en.wikipedia.org/wiki/Prefix_sum) array.',
            '##4## Each position stores arr[i] plus the running [cumulative](https://en.wikipedia.org/wiki/Cumulative_sum) tail.',
            '##5## String interpolation with `$` prints each suffix sum [entry](https://dart.dev/language/operators#string-interpolation).',
            '##6## The range-sum query uses a constant-time [subtraction](https://en.wikipedia.org/wiki/Subtraction).',
            '~~~',
            '',
            '~~~io',
            'input: a = [2, 4, 6, 8, 10], query i=1, j=3',
            'output:',
