            'sfx[1] = 28',
            'sfx[2] = 24',
            'sfx[3] = 18',
            'sfx[4] = 10',
            'Sum of a[1..3] = 18',
            '~~~',
            '',
            '## Complexity',
            '',
            '- **Time:** O(n) preprocessing, O(1) per query',
            '- **Space:** O(n) for the suffix sum array',
            '',
            '## Edge Cases',
            '',
            '- Empty array (n=0): the sentinel sfx[0]=0 and no queries can be answered',
            '- Query where i == j: returns a single element via sfx[i] - sfx[i+1]',
            '- Query spanning the full array (i=0, j=n-1): returns sfx[0] - sfx[n] = sfx[0]',
            '',
            '> [!success] Takeaway',
            '> Use suffix sums when you need repeated range-sum queries on a static array and the queries benefit from right-aligned cumulative totals.',
            '',
