DB["topics/circular-array"] = {
        title: 'Circular Array / Ring Buffer',
        crumbs: ['Home', 'Data Structures', 'Array', 'DSA & DAA Topics', 'Circular Array / Ring Buffer'],
        tags: ['array', 'circular', 'ring-buffer', 'modulo'],
        content: [
            '# Circular Array / Ring Buffer',
            '',
            '> **Definition.** A circular array (ring buffer) uses modular arithmetic to wrap indices around a fixed-size buffer, allowing efficient FIFO or fixed-size window operations without shifting elements.',
            '',
            '## History & Origin',
            '',
            'Ring buffers have been a staple in operating systems and networking for decades, used in kernel event queues and TCP buffers [Wikipedia: Circular buffer](https://en.wikipedia.org/wiki/Circular_buffer). The concept appears whenever a producer-consumer pattern needs a fixed-size queue without dynamic allocation overhead.',
            '',
            '## Intuition',
            '',
            'Imagine a fixed-size array where index `n` maps back to index `0`. By computing `i % n`, any linear sequence of insertions naturally wraps around. This means you never need to shift elements — you simply overwrite the oldest entry when the buffer is full. It is the simplest way to model infinite access to a bounded cyclic structure.',
            '',
            '## Step-by-Step Trace',
            '',
            'Buffer size n = 4, push values 1 through 7:',
            '',
            '| Step | Value | Index (val % 4) | Buffer State          |',
            '|------|-------|------------------|-----------------------|',
            '| 1    | 1     | 1                | [_, 1, _, _]          |',
            '| 2    | 2     | 2                | [_, 1, 2, _]          |',
            '| 3    | 3     | 3                | [_, 1, 2, 3]          |',
            '| 4    | 4     | 0                | [4, 1, 2, 3]          |',
            '| 5    | 5     | 1                | [4, 5, 2, 3]          |',
            '| 6    | 6     | 2                | [4, 5, 6, 3]          |',
            '| 7    | 7     | 3                | [4, 5, 6, 7]          |',
            '',
            'After 7 pushes the buffer holds [4, 5, 6, 7] — the last 4 values written.',
            '',
            '## The Program',
            '',
            '~~~explain',
            'lang: c',
            'group: circulararray',
            '#include <stdio.h>',
            '#define SIZE 4',
            'int main() {',
            '    int buf[SIZE] = {0};',
            '    for (int v = 1; v <= 7; v++) {',
            '        int idx = v % SIZE;',
            '        buf[idx] = v;',
            '        printf("Push %d -> buf[%d], state:", v, idx);',
            '        for (int i = 0; i < SIZE; i++)',
            '            printf(" %d", buf[i]);',
            '        printf("\\n");',
            '    }',
            '    return 0;',
            '}',
            '---',
            '##1## Define the fixed [buffer](https://en.wikipedia.org/wiki/Circular_buffer) size with a preprocessor macro.',
            '##2## Initialize the buffer to all zeros using an [array initializer](https://en.cppreference.com/w/c/language/array_initialization).',
            '##3## Values 1..7 are pushed; each uses [modulo](https://en.wikipedia.org/wiki/Modulo_operation) to find its slot.',
            '##4## `v % SIZE` wraps the index — the core of the [circular](https://en.wikipedia.org/wiki/Circular_buffer) pattern.',
            '##5## Print each step with [printf](https://en.cppreference.com/w/c/io/printf) to show the buffer evolving.',
            '##6## The inner loop prints all [SIZE](https://en.cppreference.com/w/cpp/language/sizeof) elements after every push.',
            '##7## Return 0 signals successful [completion](https://en.cppreference.com/w/c/program/EXIT_status).',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: circulararray',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'int main() {',
            '    ios::sync_with_stdio(false);',
            '    cin.tie(nullptr);',
            '    const int SIZE = 4;',
            '    vector<int> buf(SIZE, 0);',
            '    for (int v = 1; v <= 7; v++) {',
            '        int idx = v % SIZE;',
            '        buf[idx] = v;',
            '        cout << "Push " << v << " -> buf[" << idx << "], state:";',
            '        for (int i = 0; i < SIZE; i++)',
            '            cout << " " << buf[i];',
            '        cout << "\\n";',
            '    }',
            '    return 0;',
            '}',
            '---',
            '##1## A [vector](https://en.cppreference.com/w/cpp/container/vector) serves as the ring buffer.',
            '##2## Initialized with SIZE copies of 0 using the [fill constructor](https://en.cppreference.com/w/cpp/container/vector/vector).',
            '##3## The [modulo](https://en.wikipedia.org/wiki/Modulo_operation) operator maps each value to a buffer index.',
            '##4## Each write overwrites the oldest slot, simulating [wraparound](https://en.wikipedia.org/wiki/Circular_buffer).',
            '##5## [cout](https://en.cppreference.com/w/cpp/io/cout) prints the buffer state after each push.',
            '##6## `ios::sync_with_stdio(false)` and `cin.tie(nullptr)` speed up [I/O](https://en.cppreference.com/w/cpp/io/ios_base/sync_with_stdio).',
            '##7## The loop runs 7 times for values 1 through 7 inclusive. [vector]({cpp:vector})',
            '~~~',
            '',
            '~~~explain',
            'lang: java',
            'group: circulararray',
            'import java.util.*;',
            'public class Main {',
            '    public static void main(String[] args) {',
            '        int SIZE = 4;',
            '        int[] buf = new int[SIZE];',
            '        for (int v = 1; v <= 7; v++) {',
            '            int idx = v % SIZE;',
            '            buf[idx] = v;',
            '            System.out.print("Push " + v + " -> buf[" + idx + "], state:");',
            '            for (int i = 0; i < SIZE; i++)',
            '                System.out.print(" " + buf[i]);',
            '            System.out.println();',
            '        }',
            '    }',
            '}',
            '---',
            '##1## Import [java.util](https://docs.oracle.com/javase/8/docs/api/java/util/package-summary.html) for Scanner.',
            '##2## A plain [int array](https://docs.oracle.com/javase/tutorial/java/nutsandbasics/arrays.html) of fixed size acts as the ring buffer.',
            '##3## [Modulo](https://en.wikipedia.org/wiki/Modulo_operation) maps each value to its circular index.',
            '##4## Overwriting `buf[idx]` replaces the oldest entry, which is the essence of a [circular buffer](https://en.wikipedia.org/wiki/Circular_buffer).',
            '##5## [System.out.print](https://docs.oracle.com/javase/8/docs/api/java/io/PrintStream.html#print-java.lang.String-) prints without a newline for the state.',
            '##6## The inner loop prints all [SIZE](https://docs.oracle.com/javase/tutorial/java/nutsandbasics/arrays.html) elements.',
            '##7## `println()` after each push adds a [line break](https://docs.oracle.com/javase/8/docs/api/java/io/PrintStream.html#println--).',
            '~~~',
            '',
            '~~~explain',
            'lang: python',
            'group: circulararray',
            'def main():',
            '    SIZE = 4',
            '    buf = [0] * SIZE',
            '    for v in range(1, 8):',
            '        idx = v % SIZE',
            '        buf[idx] = v',
            '        print(f"Push {v} -> buf[{idx}], state:", end="")',
            '        for i in range(SIZE):',
            '            print(f" {buf[i]}", end="")',
            '        print()',
            'if __name__ == "__main__":',
            '    main()',
            '---',
            '##1## `SIZE` is the fixed [capacity](https://en.wikipedia.org/wiki/Circular_buffer) of the ring buffer.',
            '##2## A [list](https://docs.python.org/3/library/stdtypes.html#sequence-types-list-tuple-range) of zeros is the initial buffer state.',
            '##3## `range(1, 8)` produces values 1 through 7 for the [pushes](https://docs.python.org/3/library/stdtypes.html#range).',
            '##4## [Modulo](https://en.wikipedia.org/wiki/Modulo_operation) (`%`) gives the wraparound index.',
            '##5## An f-string formats the [push output](https://docs.python.org/3/reference/lexical_analysis.html#f-strings).',
            '##6## The inner loop prints each buffer element with `end=""` to stay on the [same line](https://docs.python.org/3/library/stdtypes.html#print).',
            '##7## A bare `print()` emits the trailing [newline](https://docs.python.org/3/library/stdtypes.html#print).',
            '##8## The `if __name__` guard prevents [auto-execution](https://docs.python.org/3/library/__main__.html).',
            '~~~',
            '',
            '~~~explain',
            'lang: dart',
            'group: circulararray',
            'void main() {',
            '  int size = 4;',
            '  List<int> buf = List<int>.filled(size, 0);',
            '  for (int v = 1; v <= 7; v++) {',
            '    int idx = v % size;',
            '    buf[idx] = v;',
            '    print(\'Push $v -> buf[$idx], state:${buf.map((e) => \' $e\').join()}\');',
            '  }',
            '}',
            '---',
            '##1## `size` defines the fixed [capacity](https://en.wikipedia.org/wiki/Circular_buffer) of the ring buffer.',
            '##2## [List.filled](https://api.dart.dev/stable/dart-core/List/List.filled.html) creates a fixed-size list initialized to zero.',
            '##3## The [for loop](https://dart.dev/language/loops#for-loops) iterates from 1 to 7 inclusive.',
            '##4## [Modulo](https://en.wikipedia.org/wiki/Modulo_operation) (`%`) provides the circular [index](https://api.dart.dev/stable/dart-core/int-class.html).',
            '##5## String interpolation with `$` formats the push [message](https://dart.dev/language/operators#string-interpolation).',
            '##6## `map` and `join` format the buffer state into a space-separated [string](https://api.dart.dev/stable/dart-core/Iterable/map.html).',
            '~~~',
            '',
            '~~~io',
            'input: none',
            'output:',
            'Push 1 -> buf[1], state: 0 1 0 0',
            'Push 2 -> buf[2], state: 0 1 2 0',
            'Push 3 -> buf[3], state: 0 1 2 3',
            'Push 4 -> buf[0], state: 4 1 2 3',
            'Push 5 -> buf[1], state: 4 5 2 3',
            'Push 6 -> buf[2], state: 4 5 6 3',
            'Push 7 -> buf[3], state: 4 5 6 7',
            '~~~',
            '',
            '## Complexity',
            '',
            '- **Time:** O(1) per push, O(n) for printing the full buffer each step',
            '- **Space:** O(n) for the fixed-size buffer',
            '',
            '## Edge Cases',
            '',
            '- Pushing exactly SIZE elements fills the buffer with no overwrites',
            '- First element always lands at index 0 (when value equals SIZE)',
            '- All-zero initial state means unwritten slots display as 0',
            '',
            '> [!success] Takeaway',
            '> Use a circular array whenever you need a fixed-size sliding window or queue that overwrites the oldest element without shifting data.',
            '',
        ].join('\n')
  };

