            '# Cyclic Sort',
            '',
            '> **Definition.** Cyclic sort is an in-place O(n) algorithm for arrays containing values 1..n, where each element is swapped to its correct position (index value-1) until every value sits in its rightful slot.',
            '',
            '## History & Origin',
            '',
            'Cyclic sort is a well-known technique in the competitive programming community, often attributed to cycle-based rearrangement strategies [Wikipedia: Cycle sort](https://en.wikipedia.org/wiki/Cycle_sort). It is a special case of the broader family of permutation cycle algorithms and is celebrated for its minimal writes — each element is moved at most once to its final position.',
            '',
            '## Intuition',
            '',
            'If every value in the array is between 1 and n and all are distinct, then value `v` belongs at index `v-1`. We scan left to right: if `a[i]` is already at its correct position, move on; otherwise swap it to where it belongs. After one pass every element is in place. The key insight is that each swap places at least one element permanently, so the total number of swaps is at most n.',
            '',
            '## Step-by-Step Trace',
            '',
            'Input: `[3, 1, 5, 2, 4]` (n=5)',
