            '| i | a[i] | a[i] == i+1? | Action | Array State     |',
            '|---|------|--------------|--------|-----------------|',
            '| 0 | 3    | no (3!=1)    | swap a[0] and a[2] | [5, 1, 3, 2, 4] |',
            '| 0 | 5    | no (5!=1)    | swap a[0] and a[4] | [4, 1, 3, 2, 5] |',
            '| 0 | 4    | no (4!=1)    | swap a[0] and a[3] | [2, 1, 3, 4, 5] |',
            '| 0 | 2    | no (2!=1)    | swap a[0] and a[1] | [1, 2, 3, 4, 5] |',
            '| 0 | 1    | yes          | i++    | [1, 2, 3, 4, 5] |',
            '| 1 | 2    | yes          | i++    | [1, 2, 3, 4, 5] |',
            '| 2 | 3    | yes          | i++    | [1, 2, 3, 4, 5] |',
            '| 3 | 4    | yes          | i++    | [1, 2, 3, 4, 5] |',
            '| 4 | 5    | yes          | i++    | [1, 2, 3, 4, 5] |',
            '',
            'Sorted: `[1, 2, 3, 4, 5]`',
            '',
            '## The Program',
            '',
            '~~~explain',
            'lang: c',
            'group: cyclicsort',
            '#include <stdio.h>',
            'int main() {',
            '    int a[] = {3, 1, 5, 2, 4};',
            '    int n = 5;',
            '    int i = 0;',
            '    while (i < n) {',
            '        int correct = a[i] - 1;',
            '        if (a[i] != a[correct]) {',
            '            int tmp = a[i];',
            '            a[i] = a[correct];',
            '            a[correct] = tmp;',
            '        } else {',
            '            i++;',
            '        }',
            '    }',
            '    for (int j = 0; j < n; j++) {',
