            '        printf("%d", a[j]);',
            '    }',
            '    printf("\\n");',
            '    return 0;',
            '}',
            '---',
            '##1## The input array contains values 1..n in [arbitrary order](https://en.wikipedia.org/wiki/Permutation).',
            '##2## `correct` is the index where `a[i]` should [belong](https://en.wikipedia.org/wiki/Cycle_sort) (value minus one).',
            '##3## If the element is not at its correct position, [swap](https://en.wikipedia.org/wiki/Swap_(computer_programming)) it there.',
            '##4## A temporary variable [exchanges](https://en.cppreference.com/w/c/language/operator_assignment) the two values.',
            '##5## After the swap, check the same index again since a new value arrived there. [c]({c:for})',
            '##6## When the element is already correct, advance [i](https://en.cppreference.com/w/c/language/for) to the next position.',
            '##7## Print the sorted array with [printf](https://en.cppreference.com/w/c/io/printf), space-separated.',
            '##8## Return 0 to signal [success](https://en.cppreference.com/w/c/program/EXIT_status).',
