            '##6## `" ".join(...)` builds the output [string](https://docs.python.org/3/library/stdtypes.html#str.join).',
            '##7## The `if __name__` guard prevents [auto-execution](https://docs.python.org/3/library/__main__.html).',
            '~~~',
            '',
