            '# Quick Select',
            '',
            '> **Definition.** A partition-based selection algorithm that finds the kth smallest element by only recursing into the partition that contains the target index.',
            '',
            '## History & Origin',
            '',
            'Quick Select was described by C.A.R. Hoare in 1961, the same inventor of quicksort. It shares the same partitioning scheme as quicksort but avoids full sorting by recursing into only one side. It is also known as Hoare\'s selection algorithm. [Selection algorithm](https://en.wikipedia.org/wiki/Selection_algorithm)',
            '',
            '## Intuition',
            '',
            'After partitioning around a pivot, the pivot lands in its final sorted position. If the pivot index matches k-1, we found it. If k-1 is smaller, the kth element is in the left partition; if larger, it is in the right. By discarding the irrelevant half at every step, we achieve O(n) average time instead of the O(n log n) that quicksort requires.',
            '',
            '## Step-by-Step Trace',
            '',
            'Array: [3, 2, 1, 5, 6, 4], k=2 (find 2nd smallest, 0-indexed target = 1)',
            '',
            '| Step | Sub-array | Pivot | p | Target | Action |',
            '|------|-----------|-------|---|--------|--------|',
            '| 1 | [3,2,1,5,6,4] | 4 | 3 | 1 | 1 < 3, go left |',
            '| 2 | [3,2,1] | 1 | 0 | 1 | 1 > 0, go right |',
            '| 3 | [2,3] | 3 | 1 | 1 | 1 == 1, return 2 |',
            '',
            '## The Program',
            '',
            '~~~explain',
            'lang: c',
            'group: quickselect',
            '#include <stdio.h>',
            'void swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }',
            'int partition(int arr[], int lo, int hi) {',
            '    int pivot = arr[hi], i = lo;',
            '    for (int j = lo; j < hi; j++) {',
            '        if (arr[j] < pivot) { swap(&arr[i], &arr[j]); i++; }',
            '    }',
            '    swap(&arr[i], &arr[hi]);',
            '    return i;',
            '}',
            'int quickSelect(int arr[], int lo, int hi, int k) {',
            '    if (lo == hi) return arr[lo];',
            '    int p = partition(arr, lo, hi);',
            '    if (k == p) return arr[p];',
            '    if (k < p) return quickSelect(arr, lo, p - 1, k);',
            '    return quickSelect(arr, p + 1, hi, k);',
            '}',
            'int main() {',
            '    int arr[] = {3, 2, 1, 5, 6, 4};',
            '    int n = 6, k = 2;',
            '    printf("%d\\n", quickSelect(arr, 0, n - 1, k - 1));',
            '    return 0;',
            '}',
            '---',
            '##1## Swap helper swaps two elements via [pointer]({c:pointer}) dereference.',
            '##2## Partition picks last element as pivot and divides around it [array]({c:array}).',
            '##3## Elements smaller than pivot are moved left of index i [for]({c:for}).',
            '##4## Final swap places pivot into its correct sorted position [pointer]({c:pointer}).',
            '##5## QuickSelect recurses into only the partition that contains k [return]({c:return}).',
            '##6## If lo equals hi the sub-array has one element which is the answer [if]({c:if}).',
            '##7## Compare pivot index with k to decide which side to recurse into [malloc]({c:malloc}).',
