            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: quickselect',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'int partition(vector<int>& arr, int lo, int hi) {',
            '    int pivot = arr[hi], i = lo;',
            '    for (int j = lo; j < hi; j++) {',
            '        if (arr[j] < pivot) { swap(arr[i], arr[j]); i++; }',
            '    }',
            '    swap(arr[i], arr[hi]);',
