            '        int pivot = arr[hi], i = lo;',
            '        for (int j = lo; j < hi; j++) {',
            '            if (arr[j] < pivot) { int t = arr[i]; arr[i] = arr[j]; arr[j] = t; i++; }',
            '        }',
            '        int t = arr[i]; arr[i] = arr[hi]; arr[hi] = t;',
            '        return i;',
            '    }',
