            'def main():',
            '    arr = [3, 2, 1, 5, 6, 4]',
            '    k = 2',
            '    print(quick_select(arr, 0, len(arr) - 1, k - 1))',
            'if __name__ == "__main__":',
            '    main()',
            '---',
            '##1## Partition unpacks pivot and boundary index using tuple [list]({python:list}).',
            '##2## Iterate over sub-range using [range]({python:range}).',
