            '  int p = partition(arr, lo, hi);',
            '  if (k == p) return arr[p];',
            '  if (k < p) return quickSelect(arr, lo, p - 1, k);',
            '  return quickSelect(arr, p + 1, hi, k);',
            '}',
            'void main() {',
            '  List<int> arr = [3, 2, 1, 5, 6, 4];',
            '  int k = 2;',
            '  print(quickSelect(arr, 0, arr.length - 1, k - 1));',
