            '',
            '## Intuition',
            '',
            'Imagine two runners on a circular track starting at the same point. One runs twice as fast as the other. If there is a loop, the faster runner will eventually catch up from behind and they will be at the same position. To find the cycle entrance, reset one runner to the starting point and advance both at the same speed — the meeting point is the cycle start. The mathematical reason is that the distance from head to cycle start equals the distance from the meeting point to cycle start around the loop.',
